func:
// 最小可用流程：不查任何外部依赖，直接回 ok
msg.statusCode = 200;
msg.headers = { "content-type": "application/json" };
msg.payload = { status: "ok", laiyuan: "node-red", shijian: new Date().toISOString() };
return msg;

// 商品列表直接透传。注意不能新建 msg，否则 msg.res 会丢，
// HTTP Response 就不知道该回哪个请求了。
if (msg.statusCode >= 200 && msg.statusCode < 300) {
    msg.statusCode = 200;
    msg.payload = { ok: true, products: (msg.payload && msg.payload.products) || [] };
} else {
    msg.statusCode = 502;
    msg.payload = { ok: false, laiyuan: "node-red", xiaoxi: "库存服务返回 " + msg.statusCode };
}
return msg;

// 输出①：合法 -> 去调库存服务
// 输出②：非法 -> 直接 400，不打扰库存服务
//
// 这一段只做「形状校验」（字段在不在、类型对不对、范围合不合理）。
// 业务校验（库存够不够、编号冲不冲突）由库存服务负责——
// 数据归谁所有，规则就归谁管，Node-RED 不越界。

const p = msg.payload;
const hui = [];

if (!p || typeof p !== "object" || Array.isArray(p)) {
    hui.push("请求体必须是 JSON 对象");
} else {
    const idGeShi = /^[A-Za-z0-9_-]{4,40}$/;
    if (!p.request_id || !idGeShi.test(String(p.request_id))) {
        hui.push("request_id 必须是 4~40 位的字母数字或 - _");
    }
    if (!p.sku || !/^[A-Za-z0-9_-]{2,20}$/.test(String(p.sku))) {
        hui.push("sku 必须是 2~20 位字母数字或 - _");
    }
    if (!Number.isInteger(p.quantity) || p.quantity <= 0) {
        hui.push("quantity 必须是正整数");
    } else if (p.quantity > 20) {
        hui.push("单次领用最多 20 件");
    }

    // 字段白名单：多传的字段直接拒，避免以后悄悄加字段就绕过校验
    const yunxu = ["request_id", "sku", "quantity"];
    const duo = Object.keys(p).filter(function (k) { return yunxu.indexOf(k) < 0; });
    if (duo.length > 0) {
        hui.push("不认识的字段：" + duo.join(","));
    }
}

if (hui.length > 0) {
    msg.statusCode = 400;
    msg.headers = { "content-type": "application/json" };
    msg.payload = { ok: false, laiyuan: "node-red", xiaoxi: hui.join("；") };
    return [null, msg];
}

// 合法：只改字段，不动 msg 本身
msg.order = {
    request_id: String(p.request_id).trim(),
    sku: String(p.sku).trim().toUpperCase(),
    quantity: p.quantity
};
msg.headers = { "content-type": "application/json" };
msg.payload = msg.order;
return [msg, null];

// ★ 本流程最关键的一段：把「业务拒绝」和「依赖故障」分开。
//
//   2xx  -> 200 成功
//   409  -> 409 业务拒绝（库存不足 / 编号内容冲突 / 超过规则上限）
//   404  -> 404 商品不存在
//   4xx  -> 400 请求问题
//   5xx  -> 502 依赖失败（库存服务自己挂了）
//
// 为什么不能一律回 200 或者一律回 500：
//   业务拒绝是「你的问题，改输入再来」；
//   依赖故障是「我的问题，等等再试」。
//   前端和重试策略要据此走完全不同的路。

const ti = msg.payload || {};
const ma = msg.statusCode;

msg.headers = { "content-type": "application/json" };

if (ma >= 200 && ma < 300) {
    msg.statusCode = 200;
    msg.payload = {
        ok: true,
        laiyuan: "node-red",
        request_id: ti.request_id,
        sku: ti.sku,
        quantity: ti.quantity,
        shengyu: ti.shengyu,
        zhuangtai: ti.zhuangtai,
        guize_banben: ti.guize_banben,
        chongfu: ti.chongfu === true,
        xiaoxi: ti.chongfu === true
            ? "同一编号的相同请求，已幂等命中，库存未重复扣减"
            : "预留成功"
    };
} else if (ma === 409) {
    msg.statusCode = 409;
    msg.payload = {
        ok: false,
        laiyuan: "node-red",
        lei_xing: ti.lei_xing || "yewu_jujue",
        xiaoxi: ti.xiaoxi || "业务拒绝",
        request_id: (msg.order && msg.order.request_id) || null,
        jiaoyi: "这是业务拒绝，改输入后可以用**同一个编号**重试（编号没被占用）"
    };
} else if (ma === 404) {
    msg.statusCode = 404;
    msg.payload = {
        ok: false, laiyuan: "node-red",
        xiaoxi: ti.xiaoxi || "商品不存在",
        sku: (msg.order && msg.order.sku) || null
    };
} else if (ma >= 400 && ma < 500) {
    msg.statusCode = 400;
    msg.payload = { ok: false, laiyuan: "node-red", xiaoxi: ti.xiaoxi || "请求有问题" };
} else {
    // 5xx：依赖失败。绝不能返回成功。
    msg.statusCode = 502;
    msg.payload = {
        ok: false,
        laiyuan: "node-red",
        lei_xing: "yilai_shibai",
        xiaoxi: "库存服务暂时不可用（原始状态 " + ma + "），请稍后重试。",
        jiaoyi: "结果未知：先用同一个编号查一次 /api/orders/{编号}，确认没扣减再重试"
    };
}

return msg;

// 支持 ?zhuangtai=已完成 这样的筛选，直接透传给库存服务
const zt = (msg.req && msg.req.query && msg.req.query.zhuangtai) || "";
msg.url = "http://127.0.0.1:8001/reservations" + (zt ? ("?zhuangtai=" + encodeURIComponent(zt)) : "");
return msg;

if (msg.statusCode >= 200 && msg.statusCode < 300) {
    msg.statusCode = 200;
    msg.payload = {
        ok: true,
        laiyuan: "node-red",
        reservations: (msg.payload && msg.payload.reservations) || [],
        zong_shu: (msg.payload && msg.payload.zong_shu) || 0
    };
} else {
    msg.statusCode = 502;
    msg.payload = { ok: false, laiyuan: "node-red", lei_xing: "yilai_shibai", xiaoxi: "查询记录失败，库存服务返回 " + msg.statusCode };
}
return msg;

const id = (msg.req && msg.req.params && msg.req.params.request_id) || "";
if (!id) {
    msg.statusCode = 400;
    msg.payload = { ok: false, laiyuan: "node-red", xiaoxi: "路径里没有请求编号" };
    return [null, msg];
}
msg.order = { request_id: decodeURIComponent(id) };
msg.url = "http://127.0.0.1:8001/reservations/" + encodeURIComponent(msg.order.request_id);
return [msg, null];

if (msg.statusCode >= 200 && msg.statusCode < 300) {
    msg.statusCode = 200;
    msg.payload = { ok: true, laiyuan: "node-red", reservation: msg.payload && msg.payload.reservation };
} else if (msg.statusCode === 404) {
    msg.statusCode = 404;
    msg.payload = { ok: false, laiyuan: "node-red", xiaoxi: "没有这个编号的记录" };
} else {
    msg.statusCode = 502;
    msg.payload = { ok: false, laiyuan: "node-red", lei_xing: "yilai_shibai", xiaoxi: "查询失败，库存服务返回 " + msg.statusCode };
}
return msg;

// 能走到这里的，基本是 HTTP Request 的网络错误/超时。
// ★ 关键认识：超时 ≠ 对方没执行。
//   所以这里不返回「失败」，而是返回「结果未知，请按编号查询」。
//   只有在一开始就明确没发出去的情况下才能断言失败。

const cuo = (msg.error && (msg.error.message || msg.error.code)) || "未知错误";

msg.statusCode = 502;
msg.headers = { "content-type": "application/json" };
msg.payload = {
    ok: false,
    laiyuan: "node-red",
    lei_xing: "wangluo_yichang",
    xiaoxi: "调用库存服务失败：" + cuo,
    jiaoyi: "结果未知。请先用同一个编号查 GET /api/orders/{编号} 确认是否已经扣减，再决定要不要重试。不要直接重复提交。"
};

// 顺手记一条到 context，方便课后看异常时间线
const xian = context.get("yichang_jilu") || [];
xian.push({ shijian: new Date().toISOString(), cuo: cuo });
if (xian.length > 50) { xian.shift(); }
context.set("yichang_jilu", xian);

return msg;

// 给运维看的：最近发生过的调用异常
msg.statusCode = 200;
msg.headers = { "content-type": "application/json" };
msg.payload = {
    ok: true,
    laiyuan: "node-red",
    yichang: context.get("yichang_jilu") || [],
    shuoming: "来自 Node-RED 文件 Context。它只有缓存和定期刷盘，不是事务，所以仅供参考，不能当业务数据。"
};
return msg;
